'use client';

import { useCallback, useEffect, useRef, useState } from 'react';

// Minimal typings: the Web Speech API is not in TypeScript's DOM lib
interface SpeechAlt { transcript: string; confidence: number }
interface SpeechResult { isFinal: boolean; length: number; [i: number]: SpeechAlt }
interface SpeechEvent { resultIndex: number; results: { length: number; [i: number]: SpeechResult } }
interface Recognition {
  lang: string;
  interimResults: boolean;
  continuous: boolean;
  maxAlternatives: number;
  onresult: ((e: SpeechEvent) => void) | null;
  onerror: ((e: { error: string }) => void) | null;
  onend: (() => void) | null;
  start: () => void;
  stop: () => void;
  abort: () => void;
}
type RecognitionCtor = new () => Recognition;

const getCtor = (): RecognitionCtor | null => {
  if (typeof window === 'undefined') return null;
  const w = window as unknown as { SpeechRecognition?: RecognitionCtor; webkitSpeechRecognition?: RecognitionCtor };
  return w.SpeechRecognition || w.webkitSpeechRecognition || null;
};

export const SPEECH_ERRORS: Record<string, { en: string; tl: string }> = {
  'not-allowed': { en: 'Microphone access is blocked. Allow it in the address bar, then try again.', tl: 'Naka-block ang mic. I-allow sa address bar tapos try ulit.' },
  'service-not-allowed': { en: 'Microphone access is blocked. Allow it in the address bar, then try again.', tl: 'Naka-block ang mic. I-allow sa address bar tapos try ulit.' },
  'no-speech': { en: "I didn't hear anything. Tap the mic and speak a bit louder.", tl: 'Wala akong narinig. Pindutin ulit ang mic at lakasan ng konti.' },
  'audio-capture': { en: 'No microphone found. Plug one in or check your settings.', tl: 'Walang nakitang mic. I-check ang settings mo.' },
  network: { en: 'Voice needs an internet connection. Check your connection and try again.', tl: 'Kailangan ng internet para sa voice. I-check ang connection mo.' },
};

interface Options {
  lang: string;
  // Called once speech ends, with the best transcript first and other guesses after it
  onFinal: (alternatives: string[]) => void;
}

export function useSpeech({ lang, onFinal }: Options) {
  const [supported, setSupported] = useState(true);
  const [listening, setListening] = useState(false);
  const [interim, setInterim] = useState('');
  const [error, setError] = useState<string | null>(null);
  const recRef = useRef<Recognition | null>(null);
  const finalRef = useRef<string[]>([]);
  const onFinalRef = useRef(onFinal);
  onFinalRef.current = onFinal;

  useEffect(() => {
    setSupported(!!getCtor());
    return () => recRef.current?.abort();
  }, []);

  const start = useCallback(() => {
    const Ctor = getCtor();
    if (!Ctor) { setSupported(false); return; }
    recRef.current?.abort();
    const rec = new Ctor();
    rec.lang = lang;
    rec.interimResults = true;
    rec.continuous = false;
    rec.maxAlternatives = 3;
    finalRef.current = [];
    setInterim('');
    setError(null);

    rec.onresult = e => {
      let text = '';
      for (let i = 0; i < e.results.length; i++) {
        const r = e.results[i];
        text += r[0].transcript;
        if (r.isFinal) {
          const alts: string[] = [];
          for (let a = 0; a < r.length; a++) alts.push(r[a].transcript.trim());
          finalRef.current = alts;
        }
      }
      setInterim(text.trim());
    };
    rec.onerror = e => {
      if (e.error !== 'aborted') setError(e.error);
    };
    rec.onend = () => {
      setListening(false);
      recRef.current = null;
      const alts = finalRef.current.filter(Boolean);
      if (alts.length) onFinalRef.current(alts);
    };

    recRef.current = rec;
    try {
      rec.start();
      setListening(true);
    } catch {
      setError('not-allowed');
    }
  }, [lang]);

  const stop = useCallback(() => recRef.current?.stop(), []);

  return { supported, listening, interim, error, start, stop, clearError: () => setError(null) };
}

// Reads a reply aloud so people do not have to look at the screen
export function speak(text: string, lang: string) {
  if (typeof window === 'undefined' || !window.speechSynthesis) return;
  window.speechSynthesis.cancel();
  const clean = text
    .replace(/₱([\d,]+(?:\.\d+)?)/g, (_, n: string) => `${n.replace(/\.00$/, '')} pesos`)
    .replace(/[•→]/g, ' ')
    .replace(/\n/g, '. ');
  const u = new SpeechSynthesisUtterance(clean);
  u.lang = lang;
  u.rate = 1.05;
  window.speechSynthesis.speak(u);
}
